$permissionLabels=['dashboard'=>'Visão geral','catalog.manage'=>'Cardápio/produtos','orders.manage'=>'Gerenciar pedidos','orders.view'=>'Consultar pedidos','orders.create'=>'Criar pedidos','orders.kitchen'=>'Cozinha/KDS','payments.manage'=>'Receber pagamentos','refunds.manage'=>'Reembolsos','fulfillment.manage'=>'Retiradas','events.manage'=>'Eventos','tickets.manage'=>'Ingressos/check-in','customers.manage'=>'Clientes/CRM','tables.manage'=>'Mesas/comandas','coupons.manage'=>'Cupons','guests.manage'=>'Convidados','promoters.manage'=>'Promotores','reports.view'=>'Relatórios','delivery.assign'=>'Atribuir entregas','units.manage'=>'Unidades','notifications.view'=>'Notificações','exports.view'=>'Exportações','waiter.calls'=>'Chamadas de mesa'];
if($_SERVER['REQUEST_METHOD']==='POST'){em_post_csrf();$action=(string)($_POST['action']??'');
    if($action==='save'){$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$email=mb_strtolower(trim((string)($_POST['email']??'')));$phone=trim((string)($_POST['phone']??''));$role=(string)($_POST['role']??'counter');$status=(string)($_POST['status']??'active');$password=(string)($_POST['password']??'');try{if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($role,$roles,true)||!in_array($status,['active','blocked'],true))throw new RuntimeException('Usuário inválido.');if($id===Auth::id()&&($status==='blocked'||$role!=='admin')&&Auth::role()==='admin')throw new RuntimeException('Você não pode bloquear ou remover sua própria função administrativa.');$pdo->beginTransaction();if($id){$u=$pdo->prepare('SELECT id FROM users WHERE id=? AND tenant_id=? FOR UPDATE');$u->execute([$id,$tenantId]);if(!$u->fetchColumn())throw new RuntimeException('Usuário não encontrado.');if($password!==''&&strlen($password)<10)throw new RuntimeException('A senha precisa ter pelo menos 10 caracteres.');if($password!=='')$pdo->prepare('UPDATE users SET name=?,email=?,phone=?,role=?,status=?,password_hash=? WHERE id=? AND tenant_id=?')->execute([$name,$email,$phone?:null,$role,$status,password_hash($password,PASSWORD_DEFAULT),$id,$tenantId]);else$pdo->prepare('UPDATE users SET name=?,email=?,phone=?,role=?,status=? WHERE id=? AND tenant_id=?')->execute([$name,$email,$phone?:null,$role,$status,$id,$tenantId]);}else{if(strlen($password)<10)throw new RuntimeException('A senha precisa ter pelo menos 10 caracteres.');$pdo->prepare('INSERT INTO users (tenant_id,name,email,phone,password_hash,role,status) VALUES (?,?,?,?,?,?,?)')->execute([$tenantId,$name,$email,$phone?:null,password_hash($password,PASSWORD_DEFAULT),$role,$status]);$id=(int)$pdo->lastInsertId();}$revoked=0;if($status==='blocked'||!in_array($role,$paymentRoles,true))$revoked=(new NfcDeviceService())->revokeForUserChange($pdo,$tenantId,$id,$status==='blocked'?'user_blocked':'payment_role_removed');if($status==='blocked'||$password!=='')$pdo->prepare('DELETE FROM remember_tokens WHERE user_id=?')->execute([$id]);$pdo->commit();if($revoked)Auth::audit('nfc.revoked_by_user_change','user',(string)$id,['devices'=>$revoked]);Auth::audit('user.saved','user',(string)$id,['role'=>$role,'status'=>$status,'remember_tokens_revoked'=>$status==='blocked'||$password!=='']);em_flash('ok','Usuário salvo. Agora você pode configurar unidades e permissões.');em_go('users',['edit'=>$id]);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();em_flash('error',$e->getMessage());em_go('users',$id?['edit'=>$id]:[]);}}
    if($action==='access-save'){$id=(int)($_POST['id']??0);try{$unitService->setUserUnits($tenantId,$id,(array)($_POST['units']??[]));foreach($permissionLabels as$key=>$label){$value=(string)(($_POST['permission'][$key]??'default'));$unitService->setPermission($tenantId,$id,$key,$value==='allow'?true:($value==='deny'?false:null));}em_flash('ok','Unidades e permissões atualizadas.');}catch(Throwable$e){em_flash('error',$e->getMessage());}em_go('users',['edit'=>$id]);}
}
$editId=(int)($_GET['edit']??0);$edit=null;if($editId){$s=$pdo->prepare('SELECT * FROM users WHERE id=? AND tenant_id=?');$s->execute([$editId,$tenantId]);$edit=$s->fetch()?:null;}$s=$pdo->prepare('SELECT u.*,(SELECT COUNT(*) FROM nfc_devices d WHERE d.user_id=u.id AND d.status="active") active_devices,(SELECT COUNT(*) FROM user_units uu WHERE uu.user_id=u.id) units_count FROM users u WHERE tenant_id=? ORDER BY status,name');$s->execute([$tenantId]);$users=$s->fetchAll();$units=$pdo->prepare('SELECT id,name,status FROM business_units WHERE tenant_id=? ORDER BY status="active" DESC,name');$units->execute([$tenantId]);$units=$units->fetchAll();$assigned=[];$overrides=[];if($edit){$q=$pdo->prepare('SELECT unit_id FROM user_units WHERE tenant_id=? AND user_id=?');$q->execute([$tenantId,$editId]);$assigned=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));$q=$pdo->prepare('SELECT permission_key,allowed FROM user_permissions WHERE tenant_id=? AND user_id=?');$q->execute([$tenantId,$editId]);foreach($q->fetchAll()as$r)$overrides[$r['permission_key']]=(bool)$r['allowed'];}
em_header('Equipe e permissões','users');?>
<div class="grid team-layout"><section class="card"><h2><?= $edit?'Editar usuário':'Novo usuário' ?></h2><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label class="span-2">Nome completo<input name="name" required value="<?= Security::e($edit['name']??'') ?>"></label><label class="span-2">E-mail<input type="email" name="email" required value="<?= Security::e($edit['email']??'') ?>"></label><label class="span-2">Telefone<input name="phone" value="<?= Security::e($edit['phone']??'') ?>"></label><label>Função<select name="role"><?php foreach($roles as$r):?><option value="<?= $r ?>"<?= em_selected($edit['role']??'counter',$r) ?>><?= Security::e(em_role_label($r)) ?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="active"<?= em_selected($edit['status']??'active','active') ?>>Ativo</option><option value="blocked"<?= em_selected($edit['status']??'','blocked') ?>>Bloqueado</option></select></label><label class="span-2"><?= $edit?'Nova senha (opcional)':'Senha' ?><input type="password" name="password" minlength="10"<?= $edit?'':' required' ?>></label><button class="primary span-2">Salvar usuário</button><?php if($edit):?><a class="button secondary span-2" href="<?= Security::e(em_url('/?route=users')) ?>">Novo usuário</a><?php endif;?></form><div class="alert" style="margin-top:16px"><strong>Regras obrigatórias</strong><br><span class="muted">Balconista, Garçom, Cozinha, Motoboy e Promotor nunca podem confirmar pagamento. Caixa não reembolsa. Gateways/NFC permanecem restritos ao Administrador/Super ADM, mesmo com permissão manual.</span></div></section><section class="card"><div class="section-head"><div><h2>Equipe</h2><span class="muted"><?= count($users) ?> usuários</span></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Usuário</th><th>Função</th><th>Unidades</th><th>Status</th><th>NFC</th><th></th></tr></thead><tbody><?php foreach($users as$u):?><tr><td><strong><?= Security::e($u['name']) ?></strong><br><span class="muted"><?= Security::e($u['email']) ?></span></td><td><span class="badge"><?= Security::e(em_role_label($u['role'])) ?></span></td><td><?= (int)$u['units_count']?:'Todas/padrão' ?></td><td><?= Security::e(em_status_label($u['status'])) ?></td><td><?= (int)$u['active_devices'] ?></td><td><a class="button secondary" href="<?= Security::e(em_url('/?route=users&edit='.(int)$u['id'])) ?>">Configurar</a></td></tr><?php endforeach;?></tbody></table></div></section></div>
<?php if($edit):?><section class="card" style="margin-top:18px"><div class="section-head"><div><h2>Acesso de <?= Security::e($edit['name']) ?></h2><span class="muted">Função padrão: <?= Security::e(em_role_label($edit['role'])) ?></span></div></div><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="access-save"><input type="hidden" name="id" value="<?= $editId ?>"><h3>Unidades permitidas</h3><?php if(!$units):?><p class="muted">Nenhuma unidade cadastrada. O usuário opera no contexto geral.</p><?php else:?><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(190px,1fr))"><?php foreach($units as$u):?><label class="checkbox" style="padding:10px;border:1px solid var(--line);border-radius:12px"><input type="checkbox" name="units[]" value="<?= (int)$u['id'] ?>"<?= in_array((int)$u['id'],$assigned,true)?' checked':'' ?><?= $u['status']!=='active'?' disabled':'' ?>> <?= Security::e($u['name']) ?> <?= $u['status']!=='active'?'<small>(inativa)</small>':'' ?></label><?php endforeach;?></div><?php endif;?><h3 style="margin-top:22px">Permissões individuais</h3><p class="muted">“Padrão da função” usa o acesso normal do cargo. Permitir/Negar cria uma exceção. Restrições de segurança continuam prevalecendo.</p><div class="table-wrap"><table class="table"><thead><tr><th>Permissão</th><th>Regra</th></tr></thead><tbody><?php foreach($permissionLabels as$key=>$label):$current=array_key_exists($key,$overrides)?($overrides[$key]?'allow':'deny'):'default';?><tr><td><strong><?= Security::e($label) ?></strong><br><small class="muted"><?= Security::e($key) ?></small></td><td><select name="permission[<?= Security::e($key) ?>]"><option value="default"<?= em_selected($current,'default') ?>>Padrão da função</option><option value="allow"<?= em_selected($current,'allow') ?>>Permitir</option><option value="deny"<?= em_selected($current,'deny') ?>>Negar</option></select></td></tr><?php endforeach;?></tbody></table></div><button class="primary" style="margin-top:14px">Salvar acessos</button></form></section><?php endif;?><?php em_footer();
